/**
 * @fileoverview Tests for use-isnan rule.
 * @author James Allardice, Michael Paulukonis
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/use-isnan"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester();

const comparisonError = {
	messageId: "comparisonWithNaN",
};

ruleTester.run("use-isnan", rule, {
	valid: [
		"var x = NaN;",
		"isNaN(NaN) === true;",
		"isNaN(123) !== true;",
		"Number.isNaN(NaN) === true;",
		"Number.isNaN(123) !== true;",
		"foo(NaN + 1);",
		"foo(1 + NaN);",
		"foo(NaN - 1)",
		"foo(1 - NaN)",
		"foo(NaN * 2)",
		"foo(2 * NaN)",
		"foo(NaN / 2)",
		"foo(2 / NaN)",
		"var x; if (x = NaN) { }",
		"var x = Number.NaN;",
		"isNaN(Number.NaN) === true;",
		"Number.isNaN(Number.NaN) === true;",
		"foo(Number.NaN + 1);",
		"foo(1 + Number.NaN);",
		"foo(Number.NaN - 1)",
		"foo(1 - Number.NaN)",
		"foo(Number.NaN * 2)",
		"foo(2 * Number.NaN)",
		"foo(Number.NaN / 2)",
		"foo(2 / Number.NaN)",
		"var x; if (x = Number.NaN) { }",
		"x === Number[NaN];",
		"x === (NaN, 1)",
		"x === (doStuff(), NaN, 1)",
		"x === (doStuff(), Number.NaN, 1)",

		//------------------------------------------------------------------------------
		// enforceForSwitchCase
		//------------------------------------------------------------------------------

		{
			code: "switch(NaN) { case foo: break; }",
			options: [{ enforceForSwitchCase: false }],
