			code: "switch(foo) { case bar: break; case 1: break; default: break; }",
			options: [{ enforceForSwitchCase: true }],
		},
		{
			code: "switch(Number.NaN) { case foo: break; }",
			options: [{ enforceForSwitchCase: false }],
