		},
		{
			code: "switch((NaN, doStuff(), 1)) {}",
			options: [{ enforceForSwitchCase: true }],
		},
		{
			code: "switch((Number.NaN, doStuff(), 1)) {}",
			options: [{ enforceForSwitchCase: true }],
		},

		//------------------------------------------------------------------------------
		// enforceForIndexOf
		//------------------------------------------------------------------------------

		"foo.indexOf(NaN)",
		"foo.lastIndexOf(NaN)",
		"foo.indexOf(Number.NaN)",
		"foo.lastIndexOf(Number.NaN)",
		{
