			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "foo.bar(NaN)",
			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "foo.IndexOf(NaN)",
			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "foo[indexOf](NaN)",
			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "foo[lastIndexOf](NaN)",
