		},
		{
			code: "function foo(NaN) { return arr.indexOf(NaN); }",
			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "function foo(NaN) { return arr.lastIndexOf(NaN); }",
			options: [{ enforceForIndexOf: true }],
		},
		{
			code: "function foo(Number) { return arr.indexOf(Number.NaN); }",
